{"file_path":"src/diff.js","content":"/**
 * Longest-common-subsequence alignment of one side against the base, and the
 * changes (runs of base lines replaced by runs of side lines) that fall out
 * of the parts the subsequence does not cover.
 */

/**
 * Align `side` against `base` with an LCS over whole lines, breaking ties
 * toward the alignment whose matches come earliest, and return the list of
 * changes needed to turn `base` into `side`.
 *
 * @param {string[]} side
 * @param {string[]} base
 * @returns {{baseStart: number, baseEnd: number, lines: string[]}[]}
 */
export function computeChanges(side, base) {
  const n = side.length
  const m = base.length

  // dp[i][j] holds the LCS length of side[i:] and base[j:]; row i+1 must
  // exist before row i is filled, so rows are built from the end backward.
  const dp = new Array(n + 1)
  dp[n] = new Uint32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    const row = new Uint32Array(m + 1)
    const next = dp[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      row[j] = side[i] === base[j] ? next[j + 1] + 1 : Math.max(next[j], row[j + 1])
    }
    dp[i] = row
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (side[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] > dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }

  const changes = []
  let prevI = 0
  let prevJ = 0
  for (const [mi, mj] of matches) {
    if (mi > prevI || mj > prevJ) {
      changes.push({ baseStart: prevJ, baseEnd: mj, lines: side.slice(prevI, mi) })
    }
    prevI = mi + 1
    prevJ = mj + 1
  }
  if (prevI < n || prevJ < m) {
    changes.push({ baseStart: prevJ, baseEnd: m, lines: side.slice(prevI, n) })
  }
  return changes
}
"}

