{"file_path":"src/merge.js","content":"/**
 * Grouping of mine's and theirs's changes against a shared base into
 * regions, and resolution of each region to stable, one-sided, matching, or
 * conflicting output.
 */

import { computeChanges } from './diff.js'

function arraysEqual(a, b) {
  return a.length === b.length && a.every((line, index) => line === b[index])
}

/**
 * Merge mine's and theirs's changes into base into the list of regions the
 * specification describes: sorted by base start with mine before theirs at
 * ties, then absorbed into a region for as long as the next change starts
 * at or before the region's current base end.
 */
function buildRegions(mineChanges, theirsChanges) {
  const combined = [
    ...mineChanges.map(change => ({ ...change, side: 'mine' })),
    ...theirsChanges.map(change => ({ ...change, side: 'theirs' })),
  ].sort((a, b) => a.baseStart - b.baseStart || (a.side === b.side ? 0 : a.side === 'mine' ? -1 : 1))

  const regions = []
  let index = 0
  while (index < combined.length) {
    const region = { baseStart: combined[index].baseStart, baseEnd: combined[index].baseEnd, changes: [combined[index]] }
    index++
    while (index < combined.length && combined[index].baseStart <= region.baseEnd) {
      region.changes.push(combined[index])
      region.baseEnd = Math.max(region.baseEnd, combined[index].baseEnd)
      index++
    }
    regions.push(region)
  }
  return regions
}

/**
 * Build one side's replacement for a region: its own changes' lines, with
 * the base lines the region covers but that side's own changes do not
 * filled in literally, per the "moved back"/"moved forward" rule.
 */
function resolveSide(sideChanges, region, base) {
  if (sideChanges.length === 0) return base.slice(region.baseStart, region.baseEnd)
  const lines = []
  let cursor = region.baseStart
  for (const change of sideChanges) {
    lines.push(...base.slice(cursor, change.baseStart))
    lines.push(...change.lines)
    cursor = change.baseEnd
  }
  lines.push(...base.slice(cursor, region.baseEnd))
  return lines
}

/**
 * Compute the ordered list of blocks a three-way merge produces: stable
 * runs of base lines, regions resolved to one side or to both sides
 * agreeing, and conflicts.
 *
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 */
export function computeBlocks(mine, base, theirs) {
  const mineChanges = computeChanges(mine, base)
  const theirsChanges = computeChanges(theirs, base)
  const regions = buildRegions(mineChanges, theirsChanges)

  const blocks = []
  let cursor = 0
  for (const region of regions) {
    if (region.baseStart > cursor) blocks.push({ kind: 'stable', lines: base.slice(cursor, region.baseStart) })

    const mineLines = resolveSide(region.changes.filter(change => change.side === 'mine'), region, base)
    const theirsLines = resolveSide(region.changes.filter(change => change.side === 'theirs'), region, base)
    const baseLines = base.slice(region.baseStart, region.baseEnd)

    if (arraysEqual(mineLines, theirsLines)) {
      blocks.push({ kind: 'both', lines: mineLines })
    } else if (arraysEqual(mineLines, baseLines)) {
      blocks.push({ kind: 'theirs', lines: theirsLines })
    } else if (arraysEqual(theirsLines, baseLines)) {
      blocks.push({ kind: 'mine', lines: mineLines })
    } else {
      blocks.push({ kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }

    cursor = region.baseEnd
  }
  if (cursor < base.length) blocks.push({ kind: 'stable', lines: base.slice(cursor, base.length) })

  return blocks
}
"}

